import fs from 'node:fs';
import path from 'node:path';
import {company as c,services,industries,teams,articles,jobs} from './site-data.mjs';
const research=JSON.parse(fs.readFileSync('research.json','utf8'));
const out='dist';fs.mkdirSync(out,{recursive:true});
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const arrow='<span aria-hidden="true">↗</span>';
const icons={people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M17 4a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5v3"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 7 7"/>',shield:'<path d="M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6zM8 12l3 3 5-6"/>',layers:'<path d="m12 2 10 6-10 6L2 8zm-10 11 10 6 10-6M2 18l10 6 10-6"/>',growth:'<path d="M3 21h19M6 17v-5m6 5V8m6 9V3M3 8l6-5 5 2 6-4"/>',building:'<path d="M4 22V3h12v19M16 10h5v12M1 22h23M8 7h4M8 11h4M8 15h4M9 22v-3h3v3"/>'};
const icon=(name)=>`<svg class="icon" width="28" height="28" viewBox="0 0 24 26" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true">${icons[name]||icons.building}</svg>`;
const a=(href,label,cls='text-link')=>`<a class="${cls}" href="${href}">${label}${arrow}</a>`;
const badge=t=>`<span class="eyebrow">${t}</span>`;
const sectionHead=(tag,title,copy='',link='')=>`<div class="section-heading"><div>${badge(tag)}<h2>${title}</h2>${copy?`<p>${copy}</p>`:''}</div>${link}</div>`;
const source=(url)=>url.includes('/jobs/')?`<p class="source"><a href="${url}" target="_blank" rel="noopener">View vacancy notification ↗</a></p>`:'';
const pending=(title,text)=>`<div class="pending">${badge('Content awaiting approval')}<h3>${title}</h3><p>${text}</p></div>`;
const cta=()=>`<section class="final-cta"><div class="wrap"><div>${badge('LET’S BUILD YOUR WORKFORCE')}<h2>The right people.<br>A stronger organization.</h2></div>${a('/contact','Talk to our team','button light')}</div></section>`;
const faq=(items,title='A few things you may be wondering.')=>`<section class="wrap section faq-layout"><div>${badge('YOUR QUESTIONS, ANSWERED')}<h2>${title}</h2><p>Have a more specific requirement?</p>${a('/contact','Let’s talk')}</div><div>${items.map(([q,v])=>`<details><summary>${q}<span aria-hidden="true">+</span></summary><p>${v}</p></details>`).join('')}</div></section>`;
const serviceRows=(list=services)=>`<div class="service-list">${list.map((s,i)=>`<a class="service-row" href="/services/${s.slug}"><span class="row-number">${String(i+1).padStart(2,'0')}</span>${icon(s.icon)}<div><h3>${s.title}</h3><p>${s.description}</p></div><span class="round-arrow" aria-hidden="true">↗</span></a>`).join('')}</div>`;
const process=()=>`<section class="wrap section" id="delivery">${sectionHead('HOW WE DELIVER','People. Processes. Accountability.','Dedicated functions support every part of the workforce journey.')}<div class="process-grid">${[['01','Understand','HR and project teams coordinate workforce and engagement requirements.'],['02','Mobilize','Recruitment and onboarding connect the right people with the defined roles.'],['03','Administer','Payroll, finance and compliance teams support workforce administration.'],['04','Support','Project SPOCs and helpdesk teams provide ongoing points of contact.']].map(([n,t,p])=>`<div><span class="step">${n}</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div>${a('/about/our-team','Meet our delivery organization')}</section>`;
const certs=[['1-1-1.png','CMMI Level 5'],['2-1-1.png','ISO 9001:2015'],['3-1-2.jpg','ISO 20000-1:2011'],['4-1.png','ISO 27001:2013'],['5-1-1.png','ISO 14001:2015'],['6-1-2.png','OHSAS 18001:2007']];
const certStrip=()=>`<section class="cert-section"><div class="wrap">${sectionHead('PROCESS & GOVERNANCE','A commitment to structured delivery.','Our commitment to quality, governance and structured delivery.',a('/about/certifications','Explore credentials'))}<div class="cert-grid">${certs.map(([im,n])=>`<div><img loading="lazy" src="/assets/${im}" alt="${n} credential badge"><span>${n}</span></div>`).join('')}</div><p class="small muted">Contact our team to confirm current certification scope and validity.</p></div></section>`;
const testimonialBlock=()=>`<section class="wrap section" id="testimonials">${sectionHead('CLIENT PERSPECTIVES','Trust deserves an authentic voice.','Verified client feedback will be shared here once approved.')}<div class="three-grid">${['Workforce delivery','Institutional partnership','People & support'].map(x=>`<div class="quote-placeholder"><span aria-hidden="true">“</span><h3>${x}</h3><p>Testimonial awaiting approved client content.</p><small>No client quote or attribution has been published.</small></div>`).join('')}</div></section>`;
const articleCards=(list=articles)=>`<div class="article-grid">${list.map((x,i)=>`<a class="article-card" href="/insights/${x.slug}" data-category="${x.category}" data-search="${esc(x.title+' '+x.summary)}">${x.image?`<img loading="lazy" src="/assets/${x.image}" alt="Illustrative workforce team reviewing operational requirements">`:`<div class="article-art art-${i}">${icon(i===1?'layers':'shield')}<span>${i===1?'PEOPLE + PROCESS':'VERIFY. PROTECT. APPLY.'}</span></div>`}<div>${badge(x.category)}<h3>${x.title}</h3><p>${x.summary}</p><span class="text-link">Read the guide ${arrow}</span></div></a>`).join('')}</div>`;
const clientTiles=(all=false)=>`<div class="client-grid">${industries.flatMap((ind)=>ind.clients.slice(0,all?4:1).map(n=>({n,cat:ind.slug}))).slice(0,all?99:8).map(({n,cat})=>`<div class="client-tile" data-category="${cat}" data-search="${esc(n)}"><span>${n}</span></div>`).join('')}</div>`;
const careerCta=()=>`<section class="career-band"><div class="wrap"><div>${badge('FOR CANDIDATES')}<h2>Your next chapter starts here.</h2><p>Explore published opportunities and find the information you need to apply with confidence.</p></div>${a('/careers','Explore careers','button outline')}</div></section>`;
const nav=[['/','Home'],['/about','About Us'],['/services','Services'],['/industries','Industries'],['/clients','Clients & Success Stories'],['/insights','Insights'],['/careers','Careers']];
function header(url){return `<a class="skip-link" href="#main">Skip to content</a><div class="utility"><div class="wrap"><span>People at the heart. Excellence in every engagement.</span><div><a href="/careers/recruitment-fraud-alert">Recruitment fraud alert ${arrow}</a><span class="utility-line"></span><a href="mailto:${c.email}">${c.email}</a></div></div></div><header class="site-header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="GA Digital home"><span class="logo-crop"><img src="/assets/cropped-logoga-1-1.png" width="261" height="100" alt="GA Digital logo"></span><span class="brand-text">GA DIGITAL<small>EXCEEDING EXPECTATIONS</small></span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="main-nav">Menu <span aria-hidden="true">☰</span></button><nav id="main-nav" aria-label="Main navigation">${nav.map(([p,n])=>`<a href="${p}"${(p==='/'?url==='/':url.startsWith(p))?' aria-current="page"':''}>${n}</a>`).join('')}${a('/contact','Contact Us','button small-button')}</nav></div></header>`}
const footer=()=>`<footer><div class="wrap"><div class="footer-intro"><div><strong>GA DIGITAL</strong><p>People. Possibility. Progress.</p></div><p>Enterprise workforce solutions.<br>Across industries. Across India.</p></div><div class="footer-grid"><div><h3>Company</h3>${[['/about','Our story'],['/about/leadership','Leadership'],['/about/our-team','Our team'],['/about/certifications','Certifications'],['/careers','Careers']].map(([u,n])=>`<a href="${u}">${n}</a>`).join('')}</div><div><h3>Our Services</h3>${services.map(s=>`<a href="/services/${s.slug}">${s.title}</a>`).join('')}<a href="/services/payroll-workforce-administration">Payroll administration</a></div><div><h3>Industries</h3>${industries.slice(0,5).map(x=>`<a href="/industries/${x.slug}">${x.name}</a>`).join('')}<a href="/industries">All industries ↗</a></div><div><h3>Resources</h3>${[['/insights','Insights'],['/clients','Clients & success stories'],['/faqs','FAQs'],['/public-notices','Public notices'],['/contact/support','Grievance & support']].map(([u,n])=>`<a href="${u}">${n}</a>`).join('')}</div><div><h3>Get in touch</h3><p>${c.address}</p><a href="tel:${c.tel}">${c.phone}</a><a href="mailto:${c.email}">${c.email}</a><a href="/contact/office-locations">Office locations ↗</a></div></div><div class="legal"><span>© 2026 ${c.name}</span><div><a href="/privacy-policy">Privacy</a><a href="/terms-conditions">Terms</a><a href="/cookie-policy">Cookies</a><a href="/recruitment-disclaimer">Recruitment disclaimer</a></div></div></div></footer>`;
const innerHero=(title,desc,tag='GA DIGITAL',extra='')=>`<section class="inner-hero"><div class="wrap">${badge(tag)}<h1>${title}</h1><p>${desc}</p>${extra}</div><span class="hero-outline" aria-hidden="true"></span></section>`;
const crumbs=(url,title)=>url==='/'?'':`<div class="wrap breadcrumbs"><a href="/">Home</a><span>/</span>${url.split('/').filter(Boolean).length>1?`<a href="/${url.split('/')[1]}">${({about:'About Us',services:'Services',industries:'Industries',clients:'Clients & Success Stories',insights:'Insights',careers:'Careers',contact:'Contact Us'})[url.split('/')[1]]||'Explore'}</a><span>/</span>`:''}<span>${title}</span></div>`;
const pages=[];
function add(url,title,description,body,options={}){pages.push({url,title,description,body,...options})}

add('/','Enterprise Workforce Solutions','GA Digital provides contract staffing, recruitment, HRM consulting, outsourcing, training and facility management across India.',`<section class="home-hero"><div class="hero-copy">${badge('ENTERPRISE WORKFORCE SOLUTIONS')}<h1>Powering businesses <br>with the <em>right <br>workforce.</em></h1><p>Connecting people, processes and possibilities.<br>Workforce solutions built for organizations<br class="desktop-break"> that move India forward.</p><div class="button-group">${a('/services','Explore our services','button')}${a('/contact','Talk to our team','hero-secondary')}</div><div class="hero-tags"><span>WORKFORCE</span><i></i><span>HR & PAYROLL</span><i></i><span>FACILITIES</span></div></div><figure class="hero-photo"><img src="/assets/workforce-hero.webp" alt="Illustrative image of industrial professionals reviewing work together" fetchpriority="high" width="1536" height="1024"><figcaption><span class="caption-mark" aria-hidden="true">↗</span><div>People who make<br><strong>progress possible.</strong></div><small>Illustrative image</small></figcaption></figure><span class="hero-side" aria-hidden="true">PEOPLE · POSSIBILITY · PROGRESS</span></section>
<section class="trust-strip"><div class="wrap"><div><strong>Since <b>2003</b></strong><span>A journey in human capital</span></div><div><strong>350<span>+</span></strong><span>Clients served across India</span></div><div><strong>11</strong><span>Zonal offices</span></div><div><strong class="pan-india">PAN-INDIA</strong><span>Presence. Local understanding.</span></div></div></section>
<section class="wrap section intro-section"><div>${badge('ABOUT GA DIGITAL')}<h2>Built around people.<br>Trusted by institutions.</h2></div><div><p class="lead">Great organizations are powered by the people behind them. We help bring those people and the processes that support them together.</p><p>GA Digital Web Word Pvt. Ltd. delivers human capital management services to public and private sector organizations. Our pan-India presence connects workforce requirements with dedicated recruitment, payroll, compliance and support teams.</p>${a('/about','Discover our story')}</div></section>
<section class="soft-bg"><div class="wrap section">${sectionHead('OUR SERVICES','The people expertise.<br>The operational support.','Workforce and allied services, built around your business requirements.',a('/services','View all services'))}${serviceRows()}</div></section>
<section class="why-section"><div class="wrap why-layout"><div>${badge('WHY GA DIGITAL')}<h2>Scale you can rely on.<br>People you can<br>connect with.</h2><p>Enterprise requirements need coordinated delivery. Our teams bring together the functions that keep people and operations moving.</p>${a('/about/our-team','The people behind our delivery','text-link on-dark')}</div><div class="why-grid">${[['01','Institutional experience','A client portfolio spanning government, public sector and enterprise organizations.'],['02','Pan-India capability','A national presence, supported by 11 zonal offices.'],['03','Compliance support','Dedicated legal and compliance functions support workforce administration.'],['04','Defined points of contact','Project SPOCs and a helpdesk connect clients and employees with the right team.']].map(([n,t,p])=>`<div><span>${n}</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></div></section>
<section class="wrap section">${sectionHead('INDUSTRIES WE SERVE','Different sectors.<br>One commitment to people.','Experience across the institutions and industries that shape India.',a('/industries','Explore industries'))}<div class="industry-grid">${industries.slice(0,6).map((x,i)=>`<a href="/industries/${x.slug}"><span class="industry-number">0${i+1}</span><h3>${x.name}</h3><p>${x.desc}</p><span class="text-link">Explore sector ${arrow}</span></a>`).join('')}</div></section>
<section class="clients-section"><div class="wrap section">${sectionHead('ORGANIZATIONS IN OUR CLIENT PORTFOLIO','In good company.','Selected organizations in GA Digital’s client portfolio.',a('/clients','Meet our clients'))}${clientTiles()}<p class="small muted">Client names do not imply endorsement or current contract status.</p></div></section>
${process()}<section class="soft-bg"><div class="wrap section">${sectionHead('FEATURED ENGAGEMENTS','Workforce needs.<br>Real institutional contexts.','A closer look at publicly documented workforce requirements.',a('/clients/key-engagements','Explore engagements'))}${engagementCards()}</div></section>${certStrip()}${testimonialBlock()}<section class="soft-bg"><div class="wrap section">${sectionHead('LATEST INSIGHTS','A practical perspective on people.','Guides for workforce planning, administration and candidate awareness.',a('/insights','Explore insights'))}${articleCards()}</div></section>${careerCta()}${cta()}`);

function engagementCards(){return `<div class="three-grid">${[['uidai','Government & Public Sector','Specialist roles at UIDAI','Published recruitment notices document contractual specialist requirements at UIDAI.'],['actrec','Healthcare','Operational support at ACTREC','A published MTS notice describes contractual placement at Tata Memorial Centre – ACTREC.'],['icmr','Research & Institutions','Project roles in health research','Published ICMR-NIHR notices describe research, technical and administrative requirements.']].map(([s,cat,t,d])=>`<a class="engagement-card" href="/clients/engagements/${s}">${badge(cat)}<h3>${t}</h3><p>${d}</p><span class="text-link">View engagement context ${arrow}</span></a>`).join('')}</div>`}

add('/services','Our Services','Explore GA Digital’s staffing, recruitment, HR consulting, outsourcing, training and facility services.',`${innerHero('Your workforce.<br>Our shared focus.','From finding the right people to supporting the way they work, explore services grounded in real operational needs.','OUR SERVICES')}<section class="wrap section">${serviceRows()}</section><section class="soft-bg"><div class="wrap section two-col"><div>${badge('AN INTEGRATED CAPABILITY')}<h2>Payroll & workforce administration.</h2></div><div><p>Payroll processing, HR administration and compliance support are documented parts of GA Digital’s outsourcing and delivery capabilities.</p>${a('/services/payroll-workforce-administration','Explore this capability')}</div></div></section>${process()}${cta()}`);
services.forEach((s,i)=>add(`/services/${s.slug}`,s.title,s.description,`${innerHero(s.short,s.description,`OUR SERVICES / ${s.title.toUpperCase()}`,a('/contact?service='+s.slug,'Discuss your requirement','button'))}<section class="wrap section two-col"><div>${badge('THE BUSINESS CONTEXT')}<h2>${i%2?'Designed around your organization.':'Support where it matters most.'}</h2></div><div><p class="lead">${s.challenge}</p><h3>Our approach</h3><p>${s.approach}</p></div></section><section class="soft-bg"><div class="wrap section">${sectionHead('KEY CAPABILITIES','A clear scope. A coordinated service.')}<div class="capability-grid">${s.capabilities.map((t,n)=>`<div><span>0${n+1}</span><h3>${t}</h3></div>`).join('')}</div>${source('https://www.gadigital.in/'+s.source+'/')}</div></section>${process()}<section class="wrap section compact-top">${sectionHead('SECTOR CONTEXT','Serving varied workforce environments.')}<div class="pill-links">${industries.filter(x=>x.services.includes(i)).map(x=>a('/industries/'+x.slug,x.name,'pill')).join('')}</div></section><section class="why-section"><div class="wrap section two-col"><div>${badge('WHY GA DIGITAL')}<h2>Connected teams.<br>National perspective.</h2></div><div><p>350+ clients served and a network of 11 zonal offices. HR, project, payroll, finance, compliance and helpdesk teams provide the delivery organization.</p>${a('/clients','View the company client portfolio','text-link on-dark')}<p class="small">Service-specific references and approved client feedback can be discussed with the team.</p></div></div></section>${faq(s.faq)}${cta()}`));
add('/services/payroll-workforce-administration','Payroll & Workforce Administration','Payroll processing and administration within GA Digital’s outsourcing and workforce delivery capabilities.',`${innerHero('People operations.<br>Carefully coordinated.','Payroll processing and HR administration, supported by dedicated payroll, finance, compliance and helpdesk functions.','PAYROLL & WORKFORCE ADMINISTRATION')}<section class="wrap section two-col"><div><h2>A capability that connects the workforce journey.</h2><p>Payroll is documented within GA Digital’s outsourcing services and operating team structure.</p></div><div><h3>Key capabilities</h3><ul class="check-list"><li>Payroll generation and processing</li><li>HR administration and employee onboarding</li><li>Salary-related queries and return filing support</li><li>EPF and ESIC-related employee support</li></ul>${source('https://www.gadigital.in/about/')}</div></section>${process()}${faq([['What needs to be agreed before payroll support begins?','Discuss workforce coverage, payroll inputs, review dates, approvals, reporting and the responsibilities of each party. The agreed scope governs delivery.'],['Where can an employee raise a salary concern?','Use the grievance and support contact route, mentioning the project and the nature of the concern. Do not submit bank credentials or sensitive identity documents through the general enquiry form.']])}${cta()}`);

add('/about','About GA Digital','Learn about GA Digital’s human capital services, June 2003 origins, leadership, teams and national presence.',`${innerHero('People are our purpose.<br>Excellence is our pursuit.','A human capital management organization supporting institutions and businesses across India.','ABOUT GA DIGITAL')}<section class="wrap section two-col"><div>${badge('OUR STORY')}<h2>A journey that began<br>in June 2003.</h2></div><div><p class="lead">GA Digital Web Word Pvt. Ltd. brings together workforce expertise and organized delivery processes.</p><p>Established in June 2003, GA Digital serves public and private sector institutions through a network of 11 zonal offices.</p><p>Truth, trust and transparency are the values at the heart of our approach.</p>${a('/about/our-journey','Explore our journey')}</div></section><section class="soft-bg"><div class="wrap section">${sectionHead('DIRECTION & VALUES','A shared belief in the potential of people.')}<div class="three-grid"><article class="plain-card"><h3>Vision</h3><p>Our vision is to become a global provider of technology-driven human capital services.</p></article><article class="plain-card"><h3>Service commitment</h3><p>Support client requirements with reliable, scalable human capital services and coordinated delivery.</p></article><article class="plain-card"><h3>Values</h3><p class="values">Truth.<br>Trust.<br>Transparency.</p></article></div>${a('/about/vision-values','Explore our direction')}</div></section>${leadership()}${process()}<section class="wrap section compact-top"><div class="link-panels">${[['/about/md-message','Director’s Message','A perspective on partnership, trust and shared progress.'],['/about/presence','Pan-India Presence','National reach supported by zonal delivery offices.']].map(([u,t,d])=>`<a href="${u}"><h3>${t} ${arrow}</h3><p>${d}</p></a>`).join('')}</div></section>${certStrip()}${cta()}`);
function leadership(){return `<section class="wrap section leader-section"><div class="leader-photo"><img loading="lazy" src="/assets/02.png" alt="Garima Arora"></div><div>${badge('LEADERSHIP')}<h2>Guided by people.<br>Driven by purpose.</h2><h3>Garima Arora</h3><p class="role">Company leader & entrepreneur</p><p>Garima Arora leads GA Digital’s human capital management journey, with a focus on innovation and integrity. Her work has received recognition through the International Icons of Excellence Awards.</p>${a('/about/leadership/garima-arora','View profile')}</div></section>`}
add('/about/leadership','Leadership','Meet the leadership behind GA Digital’s human capital management journey.',`${innerHero('Leadership with<br>people at its heart.','The people guiding the company’s direction and human capital services.','LEADERSHIP')}${leadership()}${cta()}`);
add('/about/leadership/garima-arora','Garima Arora','Garima Arora’s leadership in human capital management.',`${innerHero('Garima Arora','Company leader & entrepreneur','LEADERSHIP')}<section class="wrap section leader-section"><div class="leader-photo"><img src="/assets/02.png" alt="Garima Arora"></div><div><h2>Human capital.<br>Entrepreneurial commitment.</h2><p>Garima Arora has led the development of GA Digital’s human capital management services since the company’s inception in June 2003.</p><p>Her leadership emphasizes innovation and integrity, with recognition as “Leading Woman Entrepreneur in Human Resource” at the International Icons of Excellence Awards.</p><p>A formal designation is awaiting confirmation.</p>${source('https://www.gadigital.in/about/')}</div></section>${cta()}`);
add('/about/our-team','Our Team & Delivery Organization','Explore GA Digital’s HR, project, payroll, finance, compliance, IT and helpdesk functions.',`${innerHero('One connected<br>delivery organization.','Specialist functions support clients and employees across the workforce lifecycle.','OUR TEAM')}${process()}<section class="soft-bg"><div class="wrap section team-grid">${[...teams,['IT & MIS Support','Internal systems, employee portals, mobile applications and reporting support.']].map(([t,p],i)=>`<article><span class="row-number">0${i+1}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section>${cta()}`);
add('/about/our-journey','Our Journey','GA Digital’s company milestones and human capital management story.',`${innerHero('A journey built<br>on human potential.','From our inception in June 2003 to a client portfolio spanning India.','OUR JOURNEY')}<section class="wrap section timeline">${[['June 2003','The journey begins','GA Digital was established in June 2003.'],['Institutional experience','350+ clients served','Experience across public and private sector organizations and multiple industries.'],['National delivery presence','11 zonal offices','A network of zonal offices supports service delivery across India.']].map(([d,t,p])=>`<article><span>${d}</span><div><h2>${t}</h2><p>${p}</p></div></article>`).join('')}${source('https://www.gadigital.in/about/')}</section>${cta()}`);
add('/about/vision-values','Vision, Mission & Values','Explore GA Digital’s vision and values.',`${innerHero('Truth. Trust.<br>Transparency.','Values that define our approach to human capital services.','VISION & VALUES')}<section class="wrap section two-col"><div><h2>Our vision</h2><p class="lead">To become a global provider of technology-driven human capital services.</p>${source('https://www.gadigital.in/')}</div><div><h2>Our service commitment</h2><p>We are committed to reliable and scalable services that support clients’ strategic goals.</p>${pending('Formal mission statement','A separately approved mission statement has not been supplied. This section is reserved for company-approved wording.')}</div></section>${cta()}`);
add('/about/md-message','Director’s Message','GA Digital’s perspective on partnership, trust and shared progress.',`${innerHero('Partnership begins<br>with trust.','A perspective on partnership, trust and shared progress.','DIRECTOR’S MESSAGE')}<section class="wrap section prose"><p class="lead">Transparency and trust form the foundation of long-term relationships.</p><p>The message emphasizes putting partners’ interests at the center of the relationship, aligning priorities and drawing on experienced guidance. It describes a collaborative approach that treats partners as part of an extended team.</p><p>It also highlights decisive action, respect for timelines and ongoing development as important parts of shared progress.</p><p class="note">A signed Managing Director’s message and matching portrait await company approval.</p>${source('https://www.gadigital.in/about/','Read the original Director’s Message')}</section>${cta()}`);
add('/about/certifications','Certifications & Accreditations','GA Digital’s quality and governance credentials.',`${innerHero('A framework for<br>consistent delivery.','Quality and governance credentials supporting structured delivery.','CERTIFICATIONS & ACCREDITATIONS')}${certStrip()}<section class="wrap section prose"><h2>Credential verification</h2><p>For certificate documents, issuing bodies, certificate numbers, scope and validity dates, please contact our team.</p><p>Some displayed badges reference older standard editions. Please confirm current accreditation and certification status with our team.</p>${a('/contact?service=certification-verification','Request current certificate details','button')}${source('https://www.gadigital.in/about/')}</section>`);
add('/about/presence','Pan-India Presence','GA Digital’s 11 zonal offices and verified contact locations.',`${innerHero('National reach.<br>A connected approach.','Pan-India presence supported by 11 zonal offices.','OUR PRESENCE')}<section class="wrap section two-col"><div class="presence-graphic"><strong>11</strong><span>ZONAL OFFICES</span><p>One connected workforce partner.</p></div><div><h2>Local requirements.<br>National perspective.</h2><p>GA Digital has 11 zonal offices across India. Contact details for the headquarters and Mumbai office are available below.</p><p>Contact the team to confirm the appropriate office and delivery arrangements for your location.</p>${a('/contact/office-locations','View verified office addresses')}</div></section>${cta()}`);

add('/industries','Industries We Serve','GA Digital’s experience across government, education, healthcare, energy and other industries.',`${innerHero('Across industries.<br>Connected by people.','Workforce requirements differ. Our focus stays on understanding the context of your organization.','INDUSTRIES')}<section class="wrap section"><div class="industry-grid all-industries">${industries.map((x,i)=>`<a href="/industries/${x.slug}"><span class="industry-number">${String(i+1).padStart(2,'0')}</span><h2>${x.name}</h2><p>${x.desc}</p><span class="text-link">Explore industry ${arrow}</span></a>`).join('')}</div></section>${cta()}`);
industries.forEach(x=>add('/industries/'+x.slug,x.name,x.desc,`${innerHero(x.name,x.desc,'INDUSTRIES')}<section class="wrap section two-col"><div>${badge('INDUSTRY CONTEXT')}<h2>Understanding the work.<br>Supporting the people.</h2></div><div><p class="lead">${x.context}</p><h3>Workforce considerations</h3><p>Common planning considerations include role clarity, location coverage, onboarding documentation, administration and access to employee support. The precise requirement should be defined for each engagement.</p></div></section><section class="soft-bg"><div class="wrap section">${sectionHead('SERVICES TO DISCUSS','Support shaped around your requirements.')}${serviceRows(x.services.map(i=>services[i]))}<p class="small">These services are relevant areas for discussion, not a statement of the scope delivered to any particular client.</p></div></section><section class="wrap section">${sectionHead('OUR CLIENT PORTFOLIO','Institutional experience.')}<div class="client-grid">${x.clients.map(n=>`<div class="client-tile"><span>${n}</span></div>`).join('')}</div>${source('https://www.gadigital.in/about/')}<p>Engagement details, current contract status and sector-specific references can be discussed with the team.</p></section>${process()}${cta()}`));
add('/clients','Clients & Success Stories','Explore GA Digital’s institutional client portfolio and documented recruitment engagement contexts.',`${innerHero('Relationships built<br>around real work.','A client portfolio spanning institutions, public sector organizations and enterprises.','CLIENTS & SUCCESS STORIES')}<section class="wrap section" data-filter-group>${sectionHead('OUR CLIENTS','A breadth of institutional experience.','Selected organizations from our client portfolio.')}<div class="filter-controls"><label class="search-field">${icon('search')}<input type="search" data-search-input placeholder="Search organizations" aria-label="Search client organizations"></label><label class="select-field">Industry<select data-category-select><option value="all">All industries</option>${industries.map(x=>`<option value="${x.slug}">${x.name}</option>`).join('')}</select></label></div>${clientTiles(true)}<p class="empty-state" hidden>No matching organizations. Try a different name or industry.</p><p class="small muted">Listing does not imply endorsement or a current contract.</p>${source('https://www.gadigital.in/about/')}</section><section class="soft-bg"><div class="wrap section">${sectionHead('KEY ENGAGEMENTS','Published requirements. Meaningful context.')}${engagementCards()}</div></section><section class="wrap section">${pending('Detailed case studies','Client-approved challenges, delivery scale, governance and measured outcomes have not been supplied. Detailed case studies will be published after review.')}<div class="button-group">${a('/clients/case-studies','Case study library')}${a('/clients/testimonials','Client perspectives')}</div></section>${testimonialBlock()}${cta()}`);
add('/clients/key-engagements','Key Engagements','Explore institutional workforce contexts documented in GA Digital’s published recruitment notices.',`${innerHero('Real requirements.<br>Institutional contexts.','Engagement summaries based on published recruitment notices, with clear limits on available evidence.','KEY ENGAGEMENTS')}<section class="wrap section">${engagementCards()}</section>${cta()}`);
const engagements=[['uidai','Specialist recruitment at UIDAI','Government & Public Sector',jobs[2],'Published notices describe contractual specialist roles at UIDAI.'],['actrec','Operational support at ACTREC','Healthcare',jobs[1],'The published notice identifies GA Digital as an outsourced manpower contractor for MTS placement at Tata Memorial Centre – ACTREC.'],['icmr','Research project requirements at ICMR-NIHR','Research & Institutions',jobs[0],'The recruitment notification lists technical, research and administrative project posts associated with health research.']];
engagements.forEach(([slug,title,ind,job,summary])=>add('/clients/engagements/'+slug,title,summary,`${innerHero(title,summary,ind.toUpperCase())}<section class="wrap section detail-layout"><article class="prose"><h2>Requirement</h2><p>${job.summary}</p><h2>Workforce approach</h2><p>The published recruitment notice provides the role context and relevant application information. It does not establish the full delivery scope or project governance arrangements.</p><h2>Evidence available</h2><p>Organization, role context and published eligibility information. Availability must be confirmed against the vacancy notice.</p><h2>Scale, governance & outcomes</h2><p>Verified deployment totals, performance results and contract-specific governance information have not been provided. No outcome or client testimonial is inferred from the listing.</p>${source(job.url,'View the underlying recruitment notice')}</article><aside class="sidebar"><h3>Engagement context</h3><dl><dt>Sector</dt><dd>${ind}</dd><dt>Organization</dt><dd>${job.organization}</dd><dt>Evidence</dt><dd>Published recruitment notice</dd></dl>${a('/services/contract-staffing','Related staffing service')}${a('/contact','Discuss your workforce needs','button')}</aside></section>`));
add('/clients/case-studies','Case Studies','A library reserved for approved GA Digital workforce case studies.',`${innerHero('The story behind<br>the engagement.','A place for client-approved accounts of workforce challenges, delivery and outcomes.','CASE STUDIES')}<section class="wrap section">${pending('Case studies awaiting approval','Detailed case studies will be available once client-approved outcomes and delivery metrics are ready.')}<h2 class="space-top">Explore documented engagement contexts</h2>${engagementCards()}</section>${cta()}`);
add('/clients/testimonials','Client Testimonials','A dedicated home for verified client testimonials.',`${innerHero('Their experience.<br>In their own words.','Client perspectives will be published when approved client feedback is available.','TESTIMONIALS')}${testimonialBlock()}${cta()}`);

add('/insights','Insights','Practical workforce planning, HR administration and candidate-awareness guides.',`${innerHero('Ideas for better<br>people decisions.','Practical reading for enterprise teams and candidates navigating workforce engagements.','INSIGHTS')}<section class="wrap section" data-filter-group><div class="filter-controls"><label class="search-field">${icon('search')}<input type="search" data-search-input placeholder="Search insights" aria-label="Search insights"></label><label class="select-field">Category<select data-category-select><option value="all">All insights</option>${articles.map(x=>`<option>${x.category}</option>`).join('')}<option>Compliance Updates</option><option>Company News</option></select></label></div>${articleCards()}<p class="empty-state" hidden>No articles in this selection yet. Choose another category or clear your search.</p><p class="small muted">Practical editorial guides for workforce planning, HR administration and candidate awareness.</p></section>${cta()}`);
articles.forEach(x=>add('/insights/'+x.slug,x.title,x.summary,`${innerHero(x.title,x.summary,x.category.toUpperCase())}<section class="wrap section detail-layout"><article class="prose"><p class="article-meta">Editorial guide · 7 October 2026 · 3 min read</p>${x.body.map(([h,p])=>`<h2>${h}</h2><p>${p}</p>`).join('')}<p class="note">Confirm engagement-specific requirements directly with our team.</p>${x.slug==='recognizing-recruitment-fraud'?a('/public-notices','Read the full public notice'):a('/contact','Discuss your requirements','button')}</article><aside class="sidebar"><h3>Related services</h3>${a('/services/contract-staffing','Contract staffing')}${a('/services/payroll-workforce-administration','Payroll administration')}<h3>Continue reading</h3>${articles.filter(y=>y.slug!==x.slug).map(y=>a('/insights/'+y.slug,y.title)).join('')}</aside></section>`,{article:true}));

const candidateFaq=[['Are all published jobs still open?','No. A notice remaining online does not establish availability. Dated roles with past deadlines are marked closed; undated notices are marked availability unconfirmed. Check the vacancy notice and confirm with the company.'],['How do I apply?','Open the role page, review the eligibility and follow the vacancy notification’s application process. Different engagements may require different methods.'],['Does GA Digital charge a job-placement fee?','The formal notice dated 14 June 2025 states that no job-placement fee is charged. A separate joining notice mentions a refundable joining deposit. Read the full notices and verify any current requirement directly with the company.'],['Where can I raise a recruitment or employee concern?','Use the grievance and support page or email info@gadigital.in. Include the project or vacancy reference and a concise description of the concern.']];
const jobCards=()=>`<div class="job-list">${jobs.map(j=>`<article class="job-card" data-search="${esc(j.title+' '+j.organization+' '+j.location)}" data-category="${j.category}" data-location="${j.location}" data-type="${j.type}" data-status="${j.status.startsWith('Closed')?'closed':'unconfirmed'}"><div><span class="job-status ${j.status.startsWith('Closed')?'closed':''}">${j.status}</span><h2><a href="/careers/jobs/${j.slug}">${j.title}</a></h2><p>${j.organization}</p><div class="job-meta"><span>${j.location}</span><span>${j.category}</span><span>${j.type}</span></div></div>${a('/careers/jobs/'+j.slug,'View details')}</article>`).join('')}</div>`;
add('/careers','Careers','Explore GA Digital’s published job notices, candidate guidance and recruitment fraud information.',`${innerHero('Find your next<br>professional chapter.','Explore published workforce opportunities and the information you need to take your next step.','CAREERS',a('/careers/jobs','Explore job notices','button'))}<section class="wrap section"><div class="alert-box">${icon('shield')}<div><h2>Stay informed. Apply with confidence.</h2><p>Read the recruitment fraud alert and verify vacancy details through official company channels.</p>${a('/careers/recruitment-fraud-alert','Read the recruitment fraud alert')}</div></div></section><section class="soft-bg"><div class="wrap section two-col"><div>${badge('LIFE AT GA DIGITAL')}<h2>People supporting people.</h2></div><div><p>HR specialists, project coordinators, payroll, finance, compliance and helpdesk teams work across the workforce journey.</p><p>Explore the delivery organization and discuss current internal opportunities directly with the team.</p>${a('/careers/life-at-ga-digital','Meet the functions behind our work')}</div></div></section><section class="wrap section">${sectionHead('PUBLISHED OPPORTUNITIES','Explore the next possibility.','Availability must be confirmed. Published notices are not a live vacancy feed.',a('/careers/jobs','View all job notices'))}${jobCards()}</section>${faq(candidateFaq,'Your next step, explained.')}`);
add('/careers/jobs','Search Job Notices','Search published GA Digital job notices by keyword, location, category and status.',`${innerHero('Explore published<br>job opportunities.','Use the filters to find relevant notices. Verify the closing date and application instructions before applying.','JOB NOTICES')}<section class="wrap section" data-filter-group><p class="note">Vacancy information reviewed 7 October 2026. No role is labeled live without confirmed availability.</p><div class="job-filters"><label>Keyword<input type="search" data-search-input placeholder="Role, organization or location"></label><label>Location<select data-location-select><option value="all">All locations</option>${[...new Set(jobs.map(x=>x.location))].map(t=>`<option>${t}</option>`).join('')}</select></label><label>Category<select data-category-select><option value="all">All categories</option>${jobs.map(x=>`<option>${x.category}</option>`).join('')}</select></label><label>Status<select data-status-select><option value="all">All notices</option><option value="unconfirmed">Availability unconfirmed</option><option value="closed">Closed / archive</option></select></label><label>Engagement<select data-type-select><option value="all">All types</option><option>Contractual</option></select></label></div><p class="result-count" aria-live="polite">${jobs.length} notices</p>${jobCards()}<p class="empty-state" hidden>No notices match these filters. Try another keyword or location.</p><button class="text-link reset-filters" type="button">Clear filters ↺</button></section>${faq(candidateFaq,'Before you apply.')}`);
jobs.forEach(j=>add('/careers/jobs/'+j.slug,j.title,j.summary,`${innerHero(j.title,j.organization+' · '+j.location,'PUBLISHED JOB NOTICE')}<section class="wrap section detail-layout"><article class="prose"><span class="job-status ${j.status.startsWith('Closed')?'closed':''}">${j.status}</span><h2>Role overview</h2><p>${j.summary}</p><h2>Eligibility</h2><p>${j.requirements}</p><h2>Application guidance</h2><p>${j.instructions}</p><p class="note">This summary is not a replacement for the vacancy notification. Check the vacancy notification for complete terms and current status.</p>${source(j.url,'Read the original job notice')}</article><aside class="sidebar"><h3>At a glance</h3><dl><dt>Location</dt><dd>${j.location}</dd><dt>Category</dt><dd>${j.category}</dd><dt>Engagement</dt><dd>${j.type}</dd></dl>${j.status.startsWith('Closed')?'<p class="note">Applications closed. This notice is archived.</p>':a('/careers/apply?job='+j.slug,'Application guidance','button')}${a('/careers/recruitment-fraud-alert','Recruitment fraud alert')}</aside></section>`));
add('/careers/apply','Application Guidance','Follow the vacancy notification to apply for a GA Digital workforce role.',`${innerHero('A clear route<br>to your application.','Start with the vacancy notification and follow the process specified for your selected role.','CANDIDATE APPLICATION')}<section class="wrap section prose"><label for="application-job">Select a published role</label><select id="application-job">${jobs.map(j=>`<option value="${j.slug}" data-url="${j.url}" data-closed="${j.status.startsWith('Closed')}">${j.title} — ${j.location}</option>`).join('')}</select><div id="application-guidance" class="note" aria-live="polite"></div><ol class="numbered-list"><li>Confirm that the opportunity is still accepting applications.</li><li>Check the qualifications, experience and documents in the vacancy notification.</li><li>Apply using the email, walk-in or other method specified in that notification.</li></ol><a id="original-application" class="button" href="${jobs[0].url}" target="_blank" rel="noopener">Open application notice ↗</a><p class="small">This site does not upload or collect resumes. Applications follow the relevant vacancy notification.</p>${a('/careers/recruitment-fraud-alert','Read the recruitment fraud alert')}</section>`);
add('/careers/life-at-ga-digital','Life at GA Digital','Meet the functions supporting GA Digital’s human capital management services.',`${innerHero('Every function.<br>A shared people focus.','Explore the teams that support the company’s work with clients and employees.','LIFE AT GA DIGITAL')}<section class="wrap section team-grid">${teams.map(([t,p])=>`<article><h2>${t}</h2><p>${p}</p></article>`).join('')}</section><section class="soft-bg"><div class="wrap section prose"><h2>Interested in joining an internal team?</h2><p>Contact GA Digital to enquire about internal opportunities. No specific internal vacancy or employee benefit is represented here without approved information.</p>${a('mailto:'+c.email,'Enquire about opportunities','button')}</div></section>`);
add('/careers/faqs','Candidate FAQs','Answers about published jobs, applications, vacancy status and recruitment notices.',`${innerHero('Make your next step<br>an informed one.','Answers to common candidate questions.','CANDIDATE FAQS')}${faq(candidateFaq,'Before you apply.')}`);
const fraudContent=`<section class="wrap section prose"><h2>Verify recruitment communication</h2><p>The formal public notice dated 14 June 2025 states that GA Digital does not charge a fee for job placement and is not associated with outside brokers acting independently.</p><p>Do not rely on an intermediary promising favored placement. Confirm the vacancy, selection process and any joining requirements directly with the company.</p><h2>A separate joining notice</h2><p>A separate joining notice describes a refundable ₹10,000 security deposit at joining, payable in the company’s favor by demand draft, with no cash accepted. This is distinct from a job-placement fee. Verify current applicability directly with the company.</p><h2>Report a concern</h2><p>Email <a href="mailto:${c.email}">${c.email}</a> or call <a href="tel:${c.tel}">${c.phone}</a> using the published company contact details.</p>${a('/public-notices','Read the complete public notice','button')}</section>`;
add('/careers/recruitment-fraud-alert','Recruitment Fraud Alert','Read GA Digital’s recruitment fraud guidance and public notice.',`${innerHero('Verify first.<br>Protect your next step.','Important information about recruitment communication, placement promises and the company’s published notices.','RECRUITMENT FRAUD ALERT')}${fraudContent}`);

const offices=()=>`<div class="office-grid"><article><span class="office-index">01 / HEADQUARTERS</span><h3>Ghaziabad</h3><p>${c.address}</p>${a('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(c.address),'View on map') }<a href="tel:${c.tel}">${c.phone}</a></article><article><span class="office-index">02 / MUMBAI OFFICE</span><h3>Mumbai</h3><p>No. 117, Mastermind-I, Aarey Road, Royal Palms, Goregaon, Mumbai – 400065</p>${a('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent('117 Mastermind I Royal Palms Goregaon Mumbai 400065'),'View on map')}<a href="mailto:${c.email}">${c.email}</a></article></div>`;
add('/contact','Contact Us','Discuss workforce requirements with GA Digital. Business enquiries, office addresses and support contacts.',`${innerHero('Let’s talk about<br>your workforce.','Tell us what your organization needs. We’ll help you start the right conversation.','CONTACT GA DIGITAL')}<section class="wrap section contact-layout"><div><h2>Start a conversation.</h2><p>For staffing, HR services, training or facility requirements, share a brief outline with our team.</p><div class="contact-details"><span>EMAIL US</span><a href="mailto:${c.email}">${c.email}</a><span>CALL OUR TEAM</span><a href="tel:${c.tel}">${c.phone}</a><span>HEADQUARTERS</span><p>${c.address}</p></div><div class="support-links">${a('/careers/jobs','Looking for opportunities?')}${a('/contact/support','Employee grievance or support?')}</div></div><form id="enquiry-form" novalidate><h2>Business enquiry</h2><p class="small">All fields marked * are required.</p><div class="form-grid"><label>Full name *<input name="name" autocomplete="name" required maxlength="100"></label><label>Company *<input name="company" autocomplete="organization" required maxlength="150"></label><label>Designation<input name="designation" autocomplete="organization-title" maxlength="100"></label><label>Business email *<input name="email" type="email" autocomplete="email" required maxlength="254"></label><label>Phone *<input name="phone" type="tel" autocomplete="tel" required pattern="[+0-9() .-]{7,22}" maxlength="22"></label><label>Service interested in *<select name="service" required><option value="">Select a service</option>${services.map(s=>`<option value="${s.slug}">${s.title}</option>`).join('')}<option value="payroll-workforce-administration">Payroll administration</option><option value="certification-verification">Certification verification</option><option value="general">General enquiry</option></select></label><label class="full-width">How can we help? *<textarea name="message" rows="5" required minlength="20" maxlength="4000" placeholder="Tell us about your roles, locations, timeline or service requirements."></textarea></label></div><label class="consent"><input name="consent" type="checkbox" required> I agree to include these details in an email enquiry to GA Digital.</label><p class="form-error" id="form-error" role="alert" hidden></p><button class="button" type="submit">Prepare enquiry <span aria-hidden="true">↗</span></button><p class="small muted">Your details stay in this browser until you send the prepared email. No enquiry is submitted automatically.</p><div id="form-result" class="form-result" aria-live="polite" hidden></div></form></section><section class="soft-bg"><div class="wrap section">${sectionHead('OUR OFFICES','Connect with our team.')}${offices()}<p class="small">For other zonal-office locations, please contact our team.</p></div></section>`);
add('/contact/office-locations','Office Locations','GA Digital’s verified headquarters and Mumbai office addresses.',`${innerHero('Closer to your<br>workforce requirements.','Contact locations for GA Digital, with national delivery enquiries coordinated by the company.','OFFICE LOCATIONS')}<section class="wrap section">${offices()}${source('https://www.gadigital.in/contact/')}</section>${cta()}`);
add('/contact/support','Grievance & Support','Contact GA Digital for employee, salary, project or recruitment concerns.',`${innerHero('The right support.<br>A clear point of contact.','For employee queries, project coordination and recruitment concerns.','GRIEVANCE & SUPPORT')}<section class="wrap section two-col"><div><h2>Tell us how we can help.</h2><p>The company describes its helpdesk as the first point of contact for grievances and complaints. Employees can also contact their project SPOC.</p>${a('mailto:'+c.email+'?subject=Employee%20support%20enquiry','Email the support team','button')}<p><a href="tel:${c.tel}">${c.phone}</a></p></div><div><h3>Include the relevant context</h3><ul class="check-list"><li>Your name and contact details</li><li>Project, organization or vacancy reference</li><li>A concise description of the concern</li><li>Relevant dates and previous correspondence</li></ul><p class="note">Do not include passwords, banking credentials or full identity-document numbers in a general enquiry.</p>${a('/careers/recruitment-fraud-alert','Report a suspicious recruitment approach')}</div></section>`);
add('/faqs','Frequently Asked Questions','Answers to common business and candidate questions about GA Digital’s services.',`${innerHero('Clear answers.<br>A confident next step.','Start with these common questions or speak with the team about your requirement.','FAQS')}${faq(services[0].faq,'For organizations.')}${faq(candidateFaq,'For candidates.')}`);
add('/public-notices','Public Notices','GA Digital’s published recruitment public notice dated 14 June 2025 and separate joining notice.',`${innerHero('Important information.<br>For your awareness.','Recruitment notices and joining information for candidate awareness.','PUBLIC NOTICES')}<section class="wrap section prose"><h2>Recruitment public notice</h2><p class="article-meta">14 June 2025 · Published by GA Digital</p><div class="notice-verbatim">${esc(research.public_notice).split('\n').filter(Boolean).map(s=>`<p>${s}</p>`).join('')}</div>${source('https://www.gadigital.in/','View the original public notice')}<hr><h2>Separate joining deposit notice</h2><p>${esc(research.joining_notice||'Please contact our team for current joining security-deposit requirements.')}</p><p class="note">These notices concern different matters. Confirm current applicability and any joining requirements directly with the company.</p></section>`);
add('/recruitment-disclaimer','Recruitment Disclaimer','Recruitment notice guidance and information about vacancy availability.',`${innerHero('Recruitment information<br>you can verify.','Use vacancy notices and official company channels for application decisions.','RECRUITMENT DISCLAIMER')}${fraudContent}<section class="wrap section prose">${pending('Consolidated recruitment disclaimer','A separate approved legal disclaimer has not been provided. The recruitment notices remain available above.')}<p>Job summaries are provided for navigation. Vacancy notifications govern eligibility, dates and application instructions. An online listing does not establish an active vacancy.</p></section>`);
for(const [url,title] of [['privacy-policy','Privacy Policy'],['terms-conditions','Terms & Conditions'],['cookie-policy','Cookie Policy']])add('/'+url,title,'Reserved for company-approved '+title.toLowerCase()+' content.',`${innerHero(title,'Company-approved legal content will be published here when supplied.','LEGAL INFORMATION')}<section class="wrap section prose">${pending(title+' awaiting content','This route is prepared for approved company policy text. No policy has been invented or represented as legally approved.')}<h2>About this implementation</h2><p>${url==='cookie-policy'?'This build does not include analytics, advertising scripts or non-essential cookies.':url==='privacy-policy'?'The business enquiry form prepares an email in your browser. It does not automatically submit form data or collect resumes.':'Company-specific contractual and legal terms are awaiting approval.'}</p><p>These implementation notes are not a substitute for the company’s policy. Hosting-provider behavior and any future integrations should be included in the final approved text.</p>${a('mailto:'+c.email,'Contact the company')}</section>`,{noindex:true});

function document(p){const canonical=c.origin+(p.url==='/'?'/':p.url);const schema=[{'@context':'https://schema.org','@type':'Organization',name:c.name,url:c.origin,logo:c.origin+'/assets/cropped-logoga-1-1.png',email:c.email,telephone:c.tel,address:{'@type':'PostalAddress',streetAddress:'S-14, 2nd Floor, Aditya Mall, Indirapuram',addressLocality:'Ghaziabad',addressRegion:'Uttar Pradesh',postalCode:'201014',addressCountry:'IN'}}];if(p.url!=='/')schema.push({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Home',item:c.origin},{'@type':'ListItem',position:2,name:p.title,item:canonical}]});if(p.article)schema.push({'@context':'https://schema.org','@type':'Article',headline:p.title,description:p.description,datePublished:'2026-10-07',mainEntityOfPage:canonical});return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(p.title)} | GA Digital</title><meta name="description" content="${esc(p.description)}"><link rel="canonical" href="${canonical}"><meta name="robots" content="${p.noindex?'noindex,follow':'index,follow'}"><meta property="og:type" content="${p.article?'article':'website'}"><meta property="og:title" content="${esc(p.title)} | GA Digital"><meta property="og:description" content="${esc(p.description)}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${c.origin}/assets/workforce-hero.webp"><meta name="theme-color" content="#102a43"><link rel="icon" href="/assets/cropped-cropped-logoga-1.png"><link rel="preload" href="/assets/manrope-latin.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/styles.css"><script type="application/ld+json">${JSON.stringify(schema).replaceAll('<','\\u003c')}</script><script src="/app.js" defer></script></head><body data-route="${p.url}">${header(p.url)}<main id="main">${crumbs(p.url,p.title)}${p.body}</main>${footer()}</body></html>`}
for(const p of pages){const filename=p.url==='/'?'index.html':p.url.slice(1)+'/index.html';fs.mkdirSync(path.dirname(path.join(out,filename)),{recursive:true});fs.writeFileSync(path.join(out,filename),document(p));}
fs.writeFileSync(path.join(out,'404.html'),document({url:'/404',title:'Page Not Found',description:'Find your way back to GA Digital.',noindex:true,body:innerHero('Let’s get you<br>back on track.','We couldn’t find that page. Explore our services or return to the homepage.','404 — PAGE NOT FOUND',a('/','Return home','button'))}));
fs.writeFileSync(path.join(out,'sitemap.xml'),'<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+pages.filter(p=>!p.noindex).map(p=>`<url><loc>${c.origin}${p.url}</loc></url>`).join('')+'</urlset>');
fs.writeFileSync(path.join(out,'robots.txt'),`User-agent: *\nAllow: /\nSitemap: ${c.origin}/sitemap.xml\n`);
fs.writeFileSync('routes.json',JSON.stringify(pages.map(({url,title,noindex})=>({url,title,noindex:!!noindex})),null,2));
const manifest=JSON.parse(fs.readFileSync('.openai/hosting.json','utf8'));manifest.static={directory:'dist'};fs.writeFileSync('.openai/hosting.json',JSON.stringify(manifest,null,2)+'\n');
console.log(`Built ${pages.length} pages, 404, sitemap and robots.txt.`);
